 1  import { useMemo, useState } from 'react';
 2  import {
 3    Button,
 4    Table,
 5    TableBody,
 6    TableCell,
 7    TableHead,
 8    TableRow,
 9    TextField,
10    Toolbar,
11    Typography,
12  } from '@mui/material';
13  import { Theme } from '@mui/material/styles';
14  import makeStyles from '@mui/styles/makeStyles';
15  import { titleMinHeight } from './Dashboard';
16  import { USERS, User } from '../data/users';
17  
18  const ROW_HEIGHT = 48;
19  const VISIBLE_ROWS = 8;
20  
21  // Height of the header plus a fixed number of rows, so the page doesn't jump.
22  export const tableHeight = (theme: Theme, rows: number): number =>
23    titleMinHeight(theme) + ROW_HEIGHT * rows;
24  
25  const useStyles = makeStyles((theme: Theme) => ({
26    toolbar: {
27      padding: `${theme.spacing(1)} ${theme.spacing(2)}`,
28      justifyContent: 'space-between',
29    },
30    table: {
31      maxHeight: tableHeight(theme, VISIBLE_ROWS),
32      overflowY: 'auto',
33    },
34  }));
35  
36  function toCsv(users: User[]): string {
37    return ['name,email,role', ...users.map((u) => `${u.name},${u.email},${u.role}`)].join('\n');
38  }
39  
40  export function UsersTable({ onExport }: { onExport?: (csv: string) => void }) {
41    const classes = useStyles();
42    const [filter, setFilter] = useState('');
43    const visible = useMemo(
44      () => USERS.filter((u) => u.name.toLowerCase().includes(filter.toLowerCase())),
45      [filter],
46    );
47  
48    return (
49      <section aria-labelledby="users-title">
50        <Toolbar className={classes.toolbar}>
51          <Typography id="users-title" variant="h6" component="h1">
52            Users
53          </Typography>
54          <TextField
55            id="users-filter"
56            label="Filter by name"
57            value={filter}
58            onChange={(e) => setFilter(e.target.value)}
59            size="small"
60            variant="outlined"
61          />
62          <Button variant="outlined" onClick={() => onExport?.(toCsv(visible))}>
63            Export CSV
64          </Button>
65        </Toolbar>
66        <div className={classes.table}>
67          <Table size="small">
68            <TableHead>
69              <TableRow>
70                <TableCell>Name</TableCell>
71                <TableCell>Email</TableCell>
72                <TableCell>Role</TableCell>
73              </TableRow>
74            </TableHead>
75            <TableBody>
76              {visible.map((user) => (
77                <TableRow key={user.id}>
78                  <TableCell>{user.name}</TableCell>
79                  <TableCell>{user.email}</TableCell>
80                  <TableCell>{user.role}</TableCell>
81                </TableRow>
82              ))}
83            </TableBody>
84          </Table>
85          {visible.length === 0 && <Typography>No users match “{filter}”.</Typography>}
86        </div>
87      </section>
88    );
89  }
